const [a, b] = await Promise.all([
  tools.web_search({ queries: [
    "Reddit shutting down RSS feeds November 13 2026",
    "Reddit RSS feed deprecation 2026 announcement",
    "reddit.com/rss discontinued 2026",
  ]}),
  tools.web_search({ queries: [
    "Reddit API changes 2026 developers third party",
    "Reddit .rss endpoint removal 2026",
  ]}),
]);
const dump = (n: string, s: any) => {
  console.log("════ " + n + " ════");
  console.log((s.content ?? "(no summary)").slice(0, 1500));
  console.log(s.sources.slice(0, 10).map((x: any) => `- [${x.title ?? "?"}](${x.url})\n    ${(x.snippet ?? "").slice(0, 250)}`).join("\n"));
};
dump("A RSS shutdown", a); dump("B API changes", b);
